	// 1. Filter and normalize the string
	var filtered []rune
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			// Convert to lowercase immediately
			filtered = append(filtered, unicode.ToLower(r))
